// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Entra com e-mail e senha e abre uma sessão.
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Encerra a sessão atual e limpa o cookie.
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetMe Quem está autenticado, com papéis, permissões efetivas e o token CSRF.
	// (GET /api/v1/auth/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ChangePassword Troca a própria senha.
	// (POST /api/v1/auth/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// ConfirmPasswordReset Define a nova senha com o token de recuperação.
	// (POST /api/v1/auth/password-reset/confirm)
	ConfirmPasswordReset(ctx context.Context, request ConfirmPasswordResetRequestObject) (ConfirmPasswordResetResponseObject, error)
	// RequestPasswordReset Pede a recuperação de acesso por e-mail.
	// (POST /api/v1/auth/password-reset/request)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// ListUsers Lista usuários, do mais novo para o mais antigo, com cursor.
	// (GET /api/v1/users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)
	// CreateUser Cria um usuário só com o papel ASSOCIADO e troca de senha obrigatória.
	// (POST /api/v1/users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)
	// GrantAdminMembership Promove o usuário a administrativo (vínculo com motivo mais papéis).
	// (POST /api/v1/users/{id}/admin-membership)
	GrantAdminMembership(ctx context.Context, request GrantAdminMembershipRequestObject) (GrantAdminMembershipResponseObject, error)
	// RevokeAdminMembership Retira o acesso administrativo, com motivo; o histórico do vínculo é preservado.
	// (POST /api/v1/users/{id}/admin-membership/revoke)
	RevokeAdminMembership(ctx context.Context, request RevokeAdminMembershipRequestObject) (RevokeAdminMembershipResponseObject, error)
	// DeactivateUser Desativa o usuário, encerrando suas sessões.
	// (POST /api/v1/users/{id}/deactivate)
	DeactivateUser(ctx context.Context, request DeactivateUserRequestObject) (DeactivateUserResponseObject, error)
	// ResetUserPassword Redefinição administrativa: gera uma senha temporária, mostrada uma única vez.
	// (POST /api/v1/users/{id}/password-reset)
	ResetUserPassword(ctx context.Context, request ResetUserPasswordRequestObject) (ResetUserPasswordResponseObject, error)
	// ReactivateUser Reativa o usuário, sem restaurar papéis administrativos nem vínculo.
	// (POST /api/v1/users/{id}/reactivate)
	ReactivateUser(ctx context.Context, request ReactivateUserRequestObject) (ReactivateUserResponseObject, error)
	// SetUserRoles Substitui os papéis administrativos de quem já tem vínculo administrativo ativo.
	// (PUT /api/v1/users/{id}/roles)
	SetUserRoles(ctx context.Context, request SetUserRolesRequestObject) (SetUserRolesResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

